import asyncio
import hashlib
import json
import math
from dataclasses import dataclass, field
from typing import Any, Callable, Dict, List, Optional, Set, Tuple

# ==============================================================================
# PART 1: ReWOO PARALLEL DAG EXECUTOR WITH NEURO-SYMBOLIC UNSAT-CORE FEEDBACK
# ==============================================================================

@dataclass
class PlanNode:
    var_name: str               # e.g., "#E1"
    tool_name: str              # e.g., "query_recipe_kg"
    args: Dict[str, Any]        # May reference upstream variables like "#E1.allergies"
    dependencies: Set[str] = field(default_factory=set)

class NeuroSymbolicReWOORuntime:
    """
    Production ReWOO DAG Executor that:
      1. Resolves symbolic variable pointers (#E1.field) across steps
      2. Executes independent tool nodes concurrently via asyncio.gather
      3. Enforces deduplication guardrails against repeated identical tool calls
      4. Verifies the final state against a deterministic CSP solver with UNSAT-core feedback
    """
    def __init__(
        self,
        tools: Dict[str, Callable],
        csp_verifier: Callable[[Dict[str, Any]], Tuple[bool, List[str]]]
    ):
        self.tools = tools
        self.csp_verifier = csp_verifier
        self.call_history_hashes: Set[str] = set()

    def _resolve_args(self, raw_args: Dict[str, Any], env: Dict[str, Any]) -> Dict[str, Any]:
        resolved = {}
        for k, v in raw_args.items():
            if isinstance(v, str) and v.startswith("#E"):
                parts = v.split(".")
                val = env[parts[0]]
                for attr in parts[1:]:
                    val = val[attr] if isinstance(val, dict) else getattr(val, attr)
                resolved[k] = val
            else:
                resolved[k] = v
        return resolved

    async def execute_dag(self, plan: List[PlanNode]) -> Dict[str, Any]:
        env: Dict[str, Any] = {}
        pending = {node.var_name: node for node in plan}

        while pending:
            ready_nodes = [
                node for node in pending.values()
                if node.dependencies.issubset(env.keys())
            ]
            if not ready_nodes:
                raise RuntimeError(f"Cyclic or unresolved dependency in Agent Plan DAG: {list(pending.keys())}")

            async def _run_node(n: PlanNode) -> Tuple[str, Any]:
                resolved_kwargs = self._resolve_args(n.args, env)
                # Guardrail: Prevent duplicate identical tool calls
                call_sig = f"{n.tool_name}:{json.dumps(resolved_kwargs, sort_keys=True)}"
                call_hash = hashlib.sha256(call_sig.encode()).hexdigest()[:16]
                if call_hash in self.call_history_hashes:
                    raise ValueError(f"DUPLICATE_TOOL_CALL_BLOCKED: {call_sig}")
                self.call_history_hashes.add(call_hash)

                result = await self.tools[n.tool_name](**resolved_kwargs)
                return n.var_name, result

            # Parallel fan-out across all ready nodes in the current topological wave
            wave_results = await asyncio.gather(*(_run_node(n) for n in ready_nodes))
            for var_name, res in wave_results:
                env[var_name] = res
                del pending[var_name]

        # Run deterministic Neuro-Symbolic CSP Verifier
        is_sat, unsat_core = self.csp_verifier(env)
        if not is_sat:
            raise ValueError(f"CSP_UNSAT_CORE: Constraints violated -> {unsat_core}")
        return env


# ==============================================================================
# PART 2: LATS (LANGUAGE AGENT TREE SEARCH) MCTS ENGINE WITH HYBRID VALUE SCORE
# ==============================================================================

@dataclass
class LATSNode:
    state_id: str
    trajectory: List[str]
    parent: Optional["LATSNode"] = None
    action_taken: Optional[str] = None
    children: List["LATSNode"] = field(default_factory=list)
    visits: int = 0
    value_sum: float = 0.0
    is_terminal: bool = False

    @property
    def q_value(self) -> float:
        return self.value_sum / max(self.visits, 1)

    def uct_score(self, exploration_c: float = 1.414) -> float:
        if self.visits == 0:
            return float("inf")
        parent_visits = self.parent.visits if self.parent else 1
        exploitation = self.q_value
        exploration = exploration_c * math.sqrt(math.log(max(parent_visits, 1)) / self.visits)
        return exploitation + exploration

class LATSMCTSEngine:
    def __init__(self, exploration_c: float = 1.414):
        self.exploration_c = exploration_c

    def select_leaf(self, root: LATSNode) -> LATSNode:
        node = root
        while node.children and not node.is_terminal:
            node = max(node.children, key=lambda child: child.uct_score(self.exploration_c))
        return node

    def backpropagate(self, node: LATSNode, reward: float) -> None:
        curr: Optional[LATSNode] = node
        while curr is not None:
            curr.visits += 1
            curr.value_sum += reward
            curr = curr.parent

