# ==============================================================================
# PART 1: TOKEN-LEVEL FINITE STATE MACHINE (FSM) LOGIT MASKER & JUMP-FORWARD
# ==============================================================================

class SchemaFSMConstrainedDecoder:
    """
    Demonstrates how XGrammar / Outlines / SGLang compile a schema regex into
    token bitmasks and execute Jump-Forward decoding on deterministic paths.
    """
    def __init__(self, vocab: Dict[int, str], allowed_pattern: str):
        self.vocab = vocab  # token_id -> token_string
        self.regex = re.compile(allowed_pattern)

    def compute_valid_token_mask(self, current_prefix: str) -> List[float]:
        """
        Returns an additive logit mask: 0.0 for valid tokens, -inf for invalid tokens.
        """
        mask = []
        for tok_id in range(len(self.vocab)):
            candidate = current_prefix + self.vocab[tok_id]
            # Check if candidate matches full regex or is a valid prefix of the schema
            if self.regex.fullmatch(candidate) or self._is_valid_prefix(candidate):
                mask.append(0.0)
            else:
                mask.append(float("-inf"))
        return mask

    def jump_forward_deterministic_suffix(self, current_prefix: str) -> Optional[str]:
        """
        If only a single token in the vocabulary is valid from current_prefix,
        returns that token immediately without running a GPU forward pass!
        """
        valid_tokens = [
            self.vocab[tid]
            for tid, m in enumerate(self.compute_valid_token_mask(current_prefix))
            if m == 0.0
        ]
        if len(valid_tokens) == 1:
            return valid_tokens[0]
        return None

    def _is_valid_prefix(self, text: str) -> bool:
        # Simplified prefix check for schema demonstration
        target = '{"tool":"disburse_loan","amount":'
        return target.startswith(text) or text.startswith(target)


