# PART 2: CaMeL TAINT-TRACKED CAPABILITY ENGINE FOR MCP TOOL GATEWAYS
# ==============================================================================

@dataclass(frozen=True)
class ProvenanceTaint:
    is_tainted: bool
    sources: FrozenSet[str] = field(default_factory=frozenset)

    def merge(self, other: "ProvenanceTaint") -> "ProvenanceTaint":
        return ProvenanceTaint(
            is_tainted=self.is_tainted or other.is_tainted,
            sources=self.sources | other.sources
        )

@dataclass(frozen=True)
class TaintedValue:
    value: Any
    taint: ProvenanceTaint

class CaMeLSecureMCPGateway:
    def __init__(self, sensitive_sink_tools: Dict[str, Set[str]], hmac_secret: bytes):
        # sensitive_sink_tools maps tool_name -> set of argument names that MUST NOT be tainted
        self.sensitive_sinks = sensitive_sink_tools
        self.hmac_secret = hmac_secret

    def execute_mcp_tool(
        self,
        user_id: str,
        jwt_scopes: Set[str],
        tool_name: str,
        args: Dict[str, TaintedValue],
        hitl_signature: Optional[str] = None
    ) -> Dict[str, Any]:
        # 1. Verify OAuth2 / JWT RBAC capability scope
        required_scope = f"mcp:tool:{tool_name}"
        if required_scope not in jwt_scopes:
            raise PermissionError(f"RBAC_DENIED: User '{user_id}' lacks scope '{required_scope}'")

        # 2. Enforce CaMeL Information Flow Control on sensitive sink arguments
        if tool_name in self.sensitive_sinks:
            protected_arg_names = self.sensitive_sinks[tool_name]
            violating_args = [
                (k, list(tv.taint.sources))
                for k, tv in args.items()
                if k in protected_arg_names and tv.taint.is_tainted
            ]
            if violating_args:
                # Check if user explicitly signed off via out-of-band HITL confirmation
                canonical = f"{user_id}:{tool_name}:" + ",".join(
                    f"{k}={args[k].value}" for k in sorted(args.keys())
                )
                expected_sig = hmac.new(self.hmac_secret, canonical.encode(), hashlib.sha256).hexdigest()
                if not hitl_signature or not hmac.compare_digest(expected_sig, hitl_signature):
                    raise SecurityError(
                        f"CAMEL_TAINT_VIOLATION: Tool '{tool_name}' blocked! Protected arguments "
                        f"{violating_args} derive from untrusted external data. Out-of-band HITL required."
                    )

        clean_payload = {k: tv.value for k, tv in args.items()}
        return {"status": "SUCCESS", "tool": tool_name, "executed_args": clean_payload}

class SecurityError(Exception):
    pass

import re
import numpy as np
from dataclasses import dataclass
from typing import Any, Dict, FrozenSet, Optional, Tuple

# ==============================================================================
# PART 1: NEGATION & ENTITY-SAFE SEMANTIC CACHE (ZERO FALSE-POSITIVE COLLISIONS)
# ==============================================================================

NEGATION_WORDS = {"not", "no", "never", "without", "exclude", "except", "cannot", "don't"}

@dataclass(frozen=True)
class SymbolicFingerprint:
    tenant_id: str
    has_negation: bool
    numbers: Tuple[str, ...]
    key_entities: FrozenSet[str]

def extract_symbolic_fingerprint(tenant_id: str, query: str) -> SymbolicFingerprint:
    tokens = re.findall(r"[a-z0-9_']+", query.lower())
    has_neg = any(t in NEGATION_WORDS for t in tokens)
    nums = tuple(sorted(re.findall(r"\b\d+(?:\.\d+)?\b", query)))
    # Extract capitalized/domain tokens or long nouns as entity anchors
    entities = frozenset(t for t in tokens if len(t) >= 6 and t not in NEGATION_WORDS)
    return SymbolicFingerprint(tenant_id, has_neg, nums, entities)

class SafeEnterpriseSemanticCache:
    def __init__(self, cosine_threshold: float = 0.94):
        self.cosine_threshold = cosine_threshold
        self.entries: list[Tuple[np.ndarray, SymbolicFingerprint, str]] = []

    def lookup(self, tenant_id: str, query: str, query_emb: np.ndarray) -> Optional[str]:
        fp = extract_symbolic_fingerprint(tenant_id, query)
        norm_q = query_emb / (np.linalg.norm(query_emb) + 1e-9)

        for emb, cached_fp, response in self.entries:
            # 1. Hard Symbolic Guard: tenant, negation polarity, and numbers MUST match exactly!
            if cached_fp.tenant_id != fp.tenant_id:
                continue
            if cached_fp.has_negation != fp.has_negation:
                continue
            if cached_fp.numbers != fp.numbers:
                continue
            if cached_fp.key_entities != fp.key_entities:
                continue

            # 2. Dense Vector Cosine Check
            sim = float(np.dot(norm_q, emb))
            if sim >= self.cosine_threshold:
                return response
        return None

    def store(self, tenant_id: str, query: str, query_emb: np.ndarray, response: str) -> None:
        fp = extract_symbolic_fingerprint(tenant_id, query)
        norm_q = query_emb / (np.linalg.norm(query_emb) + 1e-9)
        self.entries.append((norm_q, fp, response))


