class AdaptiveBrownoutController:
    def __init__(self, baseline_itl_ms: float = 12.0, initial_token_limit: int = 500_000):
        self.baseline_itl_ms = baseline_itl_ms
        self.token_limit = float(initial_token_limit)

    def update_and_get_stage(self, current_ewma_itl_ms: float, hbm_kv_used_pct: float) -> Dict[str, Any]:
        gradient = min(1.0, self.baseline_itl_ms / max(current_ewma_itl_ms, 1.0))
        if gradient < 0.80 or hbm_kv_used_pct > 88.0:
            # Multiplicative decrease to prevent KV swap thrashing
            self.token_limit = max(50_000.0, self.token_limit * max(0.65, gradient))
        else:
            # Additive increase
            self.token_limit = min(2_000_000.0, self.token_limit + (self.token_limit ** 0.5))

        if hbm_kv_used_pct >= 96.0 or gradient < 0.50:
            stage = "STAGE_4_EMERGENCY_CIRCUIT_BREAKER"
        elif hbm_kv_used_pct >= 90.0 or gradient < 0.70:
            stage = "STAGE_3_CROSS_REGION_SPILL_AND_CONTEXT_PRUNE"
        elif hbm_kv_used_pct >= 80.0 or gradient < 0.85:
            stage = "STAGE_2_SHIFT_TO_8B_CAP_RETRIES"
        else:
            stage = "STAGE_1_NORMAL_FULL_CAPABILITY"

        return {
            "degradation_stage": stage,
            "latency_gradient": round(gradient, 3),
            "admitted_token_concurrency_limit": int(self.token_limit)
        }
